import type { CaseSet } from "../validate-content";

const LOANS_OK =
	"CREATE TABLE item_loans (id int GENERATED BY DEFAULT AS IDENTITY, item_id int NOT NULL, hero_id int NOT NULL, qty int NOT NULL, loaned_on date NOT NULL, returned_on date, days_out int GENERATED ALWAYS AS (returned_on - loaned_on) VIRTUAL, CONSTRAINT loans_pk PRIMARY KEY (id), CONSTRAINT loans_item_fk FOREIGN KEY (item_id) REFERENCES items ON DELETE CASCADE, CONSTRAINT loans_hero_fk FOREIGN KEY (hero_id) REFERENCES heroes, CONSTRAINT loans_qty CHECK (qty >= 1), CONSTRAINT loans_dates CHECK (loaned_on <= returned_on), CONSTRAINT loans_daily UNIQUE (item_id, loaned_on, hero_id));\n";
const GUILD_LAW = "ALTER TABLE heroes ADD CONSTRAINT heroes_guild_required CHECK (guild_id IS NOT NULL) NOT VALID;";

const cases: Record<string, CaseSet> = {
	"ch25-binding-laws/lesson-9": {
		reject: [{ sql: "ALTER TABLE heroes ADD CHECK (xp <> -1);", why: "only refuses -1" }],
		accept: ["ALTER TABLE heroes ADD CHECK (NOT xp < 0);"],
	},
	"ch25-ex01": {
		reject: [
			{ sql: "ALTER TABLE guilds ADD UNIQUE NULLS NOT DISTINCT (motto);", why: "only one guild may lack a motto" },
			{ sql: "CREATE UNIQUE INDEX ON guilds (lower(motto));", why: "case insensitive, refuses 'shh.'" },
			{ sql: "ALTER TABLE guilds ADD UNIQUE (name, motto);", why: "unique pair, not motto" },
		],
		accept: ["CREATE UNIQUE INDEX guilds_motto_idx ON guilds (motto);"],
	},
	"ch25-ex02": {
		reject: [{ sql: "CREATE UNIQUE INDEX ON items (name);", why: "case sensitive index succeeds" }],
		accept: ["CREATE UNIQUE INDEX ON items (lower(name));", "ALTER TABLE items ADD CONSTRAINT x UNIQUE (name); CREATE UNIQUE INDEX y ON items (upper(name));"],
	},
	"ch25-ex03": {
		reject: [
			{ sql: "ALTER TABLE heroes ADD CHECK (gold > 0);", why: "Grimsby's 0.00 breaks it" },
			{ sql: "ALTER TABLE heroes ADD CHECK (gold >= 0 AND gold IS NOT NULL);", why: "NULL purses break it" },
			{ sql: "ALTER TABLE heroes ADD CHECK (gold <> -1);", why: "only -1 refused" },
		],
		accept: ["ALTER TABLE heroes ADD CONSTRAINT no_debt CHECK (gold >= 0 OR gold IS NULL);", "alter table heroes add check (not gold < 0)"],
	},
	"ch25-ex04": {
		reject: [
			{ sql: "ALTER TABLE bounties ADD CHECK (hero_id BETWEEN 1 AND 30);", why: "a range is not a reference" },
			{ sql: "ALTER TABLE bounties ADD FOREIGN KEY (hero_id) REFERENCES heroes (id) ON DELETE CASCADE;", why: "deleting Mabel deletes the bounty instead of refusing" },
		],
		accept: ["ALTER TABLE bounties ADD CONSTRAINT bounties_hero_fk FOREIGN KEY (hero_id) REFERENCES heroes;"],
	},
	"ch25-ex05": {
		reject: [
			{ sql: "ALTER TABLE quest_completions DROP CONSTRAINT quest_completions_hero_id_fkey;", why: "FK dropped: orphans accepted" },
			{ sql: "ALTER TABLE heroes DROP CONSTRAINT heroes_mentor_id_fkey;\nALTER TABLE heroes ADD FOREIGN KEY (mentor_id) REFERENCES heroes (id) ON DELETE CASCADE;", why: "cascade on the wrong FK" },
			{ sql: "ALTER TABLE quest_completions DROP CONSTRAINT quest_completions_hero_id_fkey, DROP CONSTRAINT quest_completions_quest_id_fkey;\nALTER TABLE quest_completions ADD FOREIGN KEY (hero_id) REFERENCES heroes ON DELETE CASCADE, ADD FOREIGN KEY (quest_id) REFERENCES quests ON DELETE CASCADE;", why: "quest FK changed too" },
			{ sql: "ALTER TABLE quest_completions DROP CONSTRAINT quest_completions_hero_id_fkey;\nALTER TABLE quest_completions ADD FOREIGN KEY (hero_id) REFERENCES heroes (id) ON DELETE SET NULL;", why: "SET NULL on a NOT NULL column" },
		],
		accept: ["ALTER TABLE quest_completions DROP CONSTRAINT quest_completions_hero_id_fkey, ADD CONSTRAINT qc_hero_fk FOREIGN KEY (hero_id) REFERENCES heroes ON DELETE CASCADE;"],
	},
	"ch25-ex06": {
		reject: [
			{ sql: "ALTER TABLE heroes ADD COLUMN xp_to_next int;\nUPDATE heroes SET xp_to_next = level * 5000 - xp;", why: "plain column goes stale" },
			{ sql: "ALTER TABLE heroes ADD COLUMN xp_to_next int GENERATED ALWAYS AS (xp - level * 5000) STORED;", why: "sign reversed" },
		],
		accept: [
			"ALTER TABLE heroes ADD COLUMN xp_to_next int GENERATED ALWAYS AS (level * 5000 - xp);",
			"ALTER TABLE heroes ADD COLUMN xp_to_next bigint GENERATED ALWAYS AS (5000 * level - xp) VIRTUAL;",
		],
	},
	"ch25-ex07": {
		reject: [
			{ sql: "ALTER TABLE heroes DROP COLUMN height_cm;\nALTER TABLE heroes ADD COLUMN height_cm int;", why: "heights lost" },
			{ sql: "ALTER TABLE heroes ALTER COLUMN height_cm TYPE numeric USING height_cm::numeric;", why: "numeric, not int" },
		],
		accept: ["ALTER TABLE heroes ALTER COLUMN height_cm SET DATA TYPE integer USING CAST(height_cm AS integer);"],
	},
	"ch25-ex08": {
		reject: [
			{ sql: LOANS_OK + "ALTER TABLE heroes ADD CHECK (guild_id IS NOT NULL);", why: "plain CHECK fails on the wanderers" },
			{ sql: LOANS_OK, why: "guild law missing" },
			{ sql: LOANS_OK.replace(" ON DELETE CASCADE", "") + GUILD_LAW, why: "item deletion refused instead of cascading" },
			{ sql: LOANS_OK.replace("REFERENCES heroes,", "REFERENCES heroes ON DELETE CASCADE,") + GUILD_LAW, why: "hero deletion cascades" },
			{ sql: LOANS_OK.replace(", CONSTRAINT loans_daily UNIQUE (item_id, loaned_on, hero_id)", "") + GUILD_LAW, why: "same item twice the same day" },
			{ sql: LOANS_OK.replace(", CONSTRAINT loans_daily UNIQUE (item_id, loaned_on, hero_id)", ", CONSTRAINT loans_daily UNIQUE (item_id, hero_id)") + GUILD_LAW, why: "item never lent twice to the same hero" },
			{ sql: LOANS_OK.replace("days_out int GENERATED ALWAYS AS (returned_on - loaned_on) VIRTUAL", "days_out int") + GUILD_LAW, why: "days_out is a plain column" },
			{ sql: LOANS_OK.replace("CHECK (qty >= 1)", "CHECK (qty >= 0)") + GUILD_LAW, why: "zero quantity allowed" },
			{ sql: LOANS_OK.replace(", CONSTRAINT loans_dates CHECK (loaned_on <= returned_on)", "") + GUILD_LAW, why: "returned before lent" },
		],
		accept: [LOANS_OK + GUILD_LAW],
	},
	"ch25-pr01": {
		reject: [{ sql: "ALTER TABLE guards ADD UNIQUE (badge_no);", why: "NULLs may repeat" }],
	},
	"ch25-pr02": {
		reject: [{ sql: "ALTER TABLE heroes ADD CHECK (level >= 5) NOT VALID;", why: "NOT VALID succeeds" }],
	},
	"ch25-pr03": {
		reject: [{ sql: "ALTER TABLE quests ADD CHECK (reward_gold >= 0);", why: "zero allowed" }],
		accept: ["ALTER TABLE quests ADD CHECK (reward_gold >= 1);"],
	},
	"ch25-pr04": {
		reject: [{ sql: "CREATE TABLE hero_pets (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, hero_id int REFERENCES heroes (id), name text NOT NULL);", why: "owner optional" }],
		accept: ["CREATE TABLE hero_pets (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, hero_id int NOT NULL, name text NOT NULL, FOREIGN KEY (hero_id) REFERENCES heroes);"],
	},
	"ch25-pr06": {
		reject: [{ sql: "ALTER TABLE quests DROP CONSTRAINT quests_prerequisite_quest_id_fkey;\nALTER TABLE quests ADD FOREIGN KEY (prerequisite_quest_id) REFERENCES quests (id) ON DELETE CASCADE;", why: "cascade deletes Sparring Match" }],
	},
	"ch25-pr07": {
		reject: [{ sql: "ALTER TABLE items ADD COLUMN value_per_weight numeric GENERATED ALWAYS AS (round(weight / base_value, 2)) STORED;", why: "ratio inverted" }],
		accept: ["ALTER TABLE items ADD COLUMN value_per_weight numeric GENERATED ALWAYS AS (round(base_value / weight, 2)) STORED;"],
	},
	"ch25-pr08": {
		reject: [{ sql: "ALTER TABLE quests ADD COLUMN hidden boolean;\nUPDATE quests SET hidden = is_secret;", why: "old column kept" }],
	},
	"ch25-pr09": {
		reject: [{ sql: "ALTER TABLE heroes ADD COLUMN renown int DEFAULT 0;", why: "NULL renown allowed" }],
		accept: ["ALTER TABLE heroes ADD COLUMN renown int;\nUPDATE heroes SET renown = 0;\nALTER TABLE heroes ALTER COLUMN renown SET NOT NULL, ALTER COLUMN renown SET DEFAULT 0;"],
	},
};

export default cases;
